class ReactionManager:

    def __init__(self):
        self.reactions = reactions
        self.reactions_base_start = reactions_base_start
        self.reactions_add_markers = reactions_add_markers
        self.reactions_add_markers_check = reactions_add_markers_check
        self.reactions_branch_connection = reactions_branch_connection
        self.reactions_clear = reactions_clear
        self._init_branch_markers()

    def _init_branch_markers(self):
        self.branch_markers_idx = 0
        self.branch_markers = {
            0: ['55', '87'],
            1: ['56', '88'],
            2: ['57', '89'],
            3: ['58', '90'],
            4: ['59', '91'],
            5: ['60', '92'],
            6: ['61', '93'],
            7: ['62', '94'],
            8: ['63', '95'],
            9: ['64', '96'],
        }

    def reset(self):
        self.reactions = reactions
        self.reactions_add_markers = reactions_add_markers
        self.reactions_add_markers_check = reactions_add_markers_check
        self.reactions_branch_connection = reactions_branch_connection
        self.reactions_clear = reactions_clear
        self._init_branch_markers()

    def update_ring_markers(self, add=False):
        if add:
            self.branch_markers_idx += 1

        for k, v in self.reactions_add_markers.items():
            if k.startswith('3'):
                v = AllChem.ReactionToSmarts(v)
                v = v.replace(
                    self.branch_markers[self.branch_markers_idx - 1][0],
                    self.branch_markers[self.branch_markers_idx][0],
                )
                v = v.replace(
                    self.branch_markers[self.branch_markers_idx - 1][1],
                    self.branch_markers[self.branch_markers_idx][1],
                )
                self.reactions_add_markers[k] = AllChem.ReactionFromSmarts(v)

    def update_branch_markers(self, add=False):
        if add:
            self.branch_markers_idx += 1

        for k, v in self.reactions.items():
            if k.startswith('3'):
                v = AllChem.ReactionToSmarts(v)
                v = v.replace(
                    self.branch_markers[self.branch_markers_idx - 1][0],
                    self.branch_markers[self.branch_markers_idx][0],
                )
                v = v.replace(
                    self.branch_markers[self.branch_markers_idx - 1][1],
                    self.branch_markers[self.branch_markers_idx][1],
                )
                self.reactions[k] = AllChem.ReactionFromSmarts(v)

        for k, v in self.reactions_branch_connection.items():
            v = AllChem.ReactionToSmarts(v)
            v = v.replace(
                self.branch_markers[self.branch_markers_idx - 1][0],
                self.branch_markers[self.branch_markers_idx][0],
            )
            v = v.replace(
                self.branch_markers[self.branch_markers_idx - 1][1],
                self.branch_markers[self.branch_markers_idx][1],
            )
            self.reactions_branch_connection[k] = AllChem.ReactionFromSmarts(v)

        for k, v in self.reactions_clear.items():
            v = AllChem.ReactionToSmarts(v)
            v = v.split(']>>')[0] + ',#' + self.branch_markers[self.branch_markers_idx][0] + ',#' + self.branch_markers[self.branch_markers_idx][1] + ']>>' + v.split(']>>')[1]
            self.reactions_clear[k] = AllChem.ReactionFromSmarts(v)

    def get_branch_markers(self, idx):

        for reactions in [self.reactions, self.reactions_add_markers]:
            for k, v in reactions.items():
                v = AllChem.ReactionToSmarts(v)
                v = v.replace(
                    self.branch_markers[self.branch_markers_idx][0],
                    self.branch_markers[idx][0],
                )
                v = v.replace(
                    self.branch_markers[self.branch_markers_idx][1],
                    self.branch_markers[idx][1],
                )
                reactions[k] = AllChem.ReactionFromSmarts(v)

        for k, v in self.reactions_branch_connection.items():
            v = AllChem.ReactionToSmarts(v)
            v = v.replace(
                self.branch_markers[self.branch_markers_idx][0],
                self.branch_markers[idx][0],
            )
            v = v.replace(
                self.branch_markers[self.branch_markers_idx][1],
                self.branch_markers[idx][1],
            )
            self.reactions_branch_connection[k] = AllChem.ReactionFromSmarts(v)

        self.branch_markers_idx = idx
